}

.theme-modern .toggle-btn-active {
  background: #0f172a !important;
  color: #ffffff !important;
  border-color: #0f172a !important;
}


/* 2. Classic Theme (アンティーク・高級真鍮調) */
.theme-classic.clock-app {
  background: radial-gradient(circle at 50% 20%, #2a221b 0%, #15100c 100%);
  color: #e8d8b8;
}

.theme-classic .analog-clock-container {
  background: #fbf7ee;
  border: 12px solid #8e6c3e;
  box-shadow:
    0 24px 50px -10px rgba(0, 0, 0, 0.65),
    0 0 0 2px #d4af37,
    0 0 0 6px #5e4624,
    inset 0 3px 8px rgba(94, 70, 36, 0.4);
}

.theme-classic .clock-face {
  background: radial-gradient(circle at center, #fffdf8 55%, #ede1cb 100%);
}

.theme-classic .clock-tick {
  background-color: #8c7853;
}

.theme-classic .clock-tick-major {
  background-color: #3c2a1a;
  height: 16px;
  width: 4px;
}

.theme-classic .clock-number {
  color: #2b1d0c;
  font-family: var(--font-serif);
  font-weight: 700;
  letter-spacing: 0.05em;
}

.theme-classic .hour-hand {
  background: linear-gradient(to top, #1a1105, #3a2712);
  clip-path: polygon(50% 0%, 100% 70%, 75% 100%, 25% 100%, 0% 70%);
  border-radius: 0;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.3);
}

.theme-classic .minute-hand {
  background: linear-gradient(to top, #2b1d0c, #4a3620);
  clip-path: polygon(50% 0%, 100% 80%, 75% 100%, 25% 100%, 0% 80%);
