}

.theme-dark .controls-panel {
  background: rgba(22, 27, 34, 0.85);
  border: 1px solid rgba(56, 68, 86, 0.6);
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.5);
}

.theme-dark .theme-btn {
  background: #222933;
  color: #94a3b8;
  border-color: #333d4b;
}

.theme-dark .theme-btn:hover {
  background: #2d3748;
  color: #f1f5f9;
}

.theme-dark .theme-btn-active {
  background: #0ea5e9 !important;
  color: #ffffff !important;
  border-color: #38bdf8 !important;
  box-shadow: 0 3px 12px rgba(14, 165, 233, 0.35);
}

.theme-dark .toggle-btn {
  background: #222933;
  color: #94a3b8;
  border-color: #333d4b;
}

.theme-dark .toggle-btn:hover {
  background: #2d3748;
  color: #f1f5f9;
}

.theme-dark .toggle-btn-active {
  background: #38bdf8 !important;
  color: #0f172a !important;
  border-color: #7dd3fc !important;
  font-weight: 700;
}


/* 4. Neon Theme (フューチャー・サイバーパンク) */
.theme-neon.clock-app {
  background: radial-gradient(circle at 50% 25%, #0f051d 0%, #05020a 100%);
  color: #00f2fe;
