  border: 1px solid rgba(0, 242, 254, 0.5);
  box-shadow:
    0 0 20px rgba(0, 242, 254, 0.25),
    inset 0 0 15px rgba(0, 242, 254, 0.1);
}

.theme-neon .digital-time {
