import { useState, useEffect, useCallback, useMemo } from 'react';
import { ClockSettings } from './types';
import AnalogClock from './components/AnalogClock';
import ClockControls from './components/ClockControls';
import './index.css';

const DEFAULT_SETTINGS: ClockSettings = {
  theme: 'modern',
  movement: 'sweep',
  showDigital: true,
  showSeconds: true,
  showNumbers: true,
};

const WEEKDAY_NAMES = ['日', '月', '火', '水', '木', '金', '土'];

const App = () => {
  const [settings, setSettings] = useState<ClockSettings>(DEFAULT_SETTINGS);
  const [currentTime, setCurrentTime] = useState<Date>(() => new Date());

  // 高精度かつ滑らかなフレーム同期アニメーションループ
  useEffect(() => {
    let animationFrameId: number;

    const updateLoop = () => {
      setCurrentTime(new Date());
      animationFrameId = requestAnimationFrame(updateLoop);
    };

    animationFrameId = requestAnimationFrame(updateLoop);

    return () => {
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  // 設定更新ハンドラー
  const handleUpdateSettings = useCallback(
    <K extends keyof ClockSettings>(key: K, value: ClockSettings[K]) => {
      setSettings((prev) => ({
        ...prev,
        [key]: value,
      }));
    },
    []
  );

  // デジタル時計フォーマット処理
  const formattedDigitalTime = useMemo(() => {
    const hours = String(currentTime.getHours()).padStart(2, '0');
    const minutes = String(currentTime.getMinutes()).padStart(2, '0');
    const seconds = String(currentTime.getSeconds()).padStart(2, '0');

    if (settings.showSeconds) {
      return `${hours}:${minutes}:${seconds}`;
    }
    return `${hours}:${minutes}`;
  }, [currentTime, settings.showSeconds]);

  // 和暦および年月日・曜日のフォーマット
  const formattedDate = useMemo(() => {
    const year = currentTime.getFullYear();
    const month = currentTime.getMonth() + 1;
    const date = currentTime.getDate();
    const dayName = WEEKDAY_NAMES[currentTime.getDay()];

    // 令和年計算 (2019年が令和元年)
    const reiwaYear = year - 2018;
    const eraStr = reiwaYear === 1 ? '令和元年' : `令和${reiwaYear}年`;

    return `${year}年（${eraStr}）${month}月${date}日（${dayName}）`;
  }, [currentTime]);

  return (
    <div className={`clock-app theme-${settings.theme}`}>
      <header className="clock-header">
        <h1 className="clock-title">プレミアム・クロック</h1>
        <p className="clock-subtitle">高精度アナログ運針 &amp; 多機能カスタマイズ時計</p>
      </header>

      <main className="clock-main-layout">
        {/* 左側：アナログ時計とデジタル表示エリア */}
        <div className="clock-stage">
          <AnalogClock currentTime={currentTime} settings={settings} />

          {/* デジタル情報ボックス */}
          {settings.showDigital && (
            <div className="digital-display-box" aria-live="off">
              <div className="digital-time">{formattedDigitalTime}</div>
              <div className="digital-date">{formattedDate}</div>
            </div>
          )}
        </div>

        {/* 右側：設定コントローラー */}
        <ClockControls settings={settings} onUpdateSettings={handleUpdateSettings} />
      </main>

      <footer className="footer-info">
        <p>リアルタイム同期エンジン稼働中 | スイープ運針・ステップ運針対応</p>
      </footer>
    </div>
  );
};

export default App;
